mapper.select:
SELECT

FROM lottery_theme_alias
WHERE theme_id = #{themeId}

  AND status = #{status}

ORDER BY created_at ASC

mapper.insert:
INSERT INTO lottery_theme_alias (
  id, theme_id, alias_name, normalized_name, status, created_at, updated_at
) VALUES (
  #{id}, #{themeId}, #{aliasName}, #{normalizedName}, #{status}, #{createdAt}, #{updatedAt}
)

mapper.update:
UPDATE lottery_theme_alias
theme_id = #{themeId}, alias_name = #{aliasName}, normalized_name = #{normalizedName}, status = #{status}, updated_at = NOW()
WHERE id = #{id}
